#import "MapPanel.h"
#import <UIKit/UIKit.h>
@interface MapTiles : NSObject <WKURLSchemeHandler>
@property NSURLSession *session;
@property NSArray<NSDictionary *> *sources;
@property NSMutableDictionary<NSValue *,NSURLSessionDataTask *> *tasks;
@property(nonatomic,copy) void (^failure)(NSString *message);
@end
@implementation MapTiles
- (instancetype)init{if((self=[super init])){_tasks=[NSMutableDictionary dictionary];NSData *data=[NSData dataWithContentsOfURL:[NSBundle.mainBundle URLForResource:@"sources" withExtension:@"json" subdirectory:@"Map"]];_sources=data?[NSJSONSerialization JSONObjectWithData:data options:0 error:nil]:@[];NSURLSessionConfiguration *c=NSURLSessionConfiguration.defaultSessionConfiguration;c.timeoutIntervalForRequest=24;c.timeoutIntervalForResource=35;c.HTTPMaximumConnectionsPerHost=4;c.HTTPAdditionalHeaders=@{@"User-Agent":[NSString stringWithFormat:@"loc-x/%@ (+https://github.com/gitfengxx/loc-x)",[NSBundle.mainBundle objectForInfoDictionaryKey:@"CFBundleShortVersionString"]?:@"unknown"]};c.URLCache=[[NSURLCache alloc]initWithMemoryCapacity:16*1024*1024 diskCapacity:80*1024*1024 diskPath:@"wloc-map-tiles"];_session=[NSURLSession sessionWithConfiguration:c];}return self;}
- (void)webView:(WKWebView *)webView startURLSchemeTask:(id<WKURLSchemeTask>)task{
 NSURL *url=task.request.URL;NSArray *p=url.path.pathComponents;NSDictionary *source=nil;for(NSDictionary *candidate in self.sources)if([candidate[@"id"]isEqual:url.host]){source=candidate;break;}BOOL valid=p.count==4&&source!=nil;
 NSInteger z=0,x=0,y=0;if(valid){for(NSUInteger i=1;i<4;i++){NSString *s=p[i];if(!s.length||[s rangeOfCharacterFromSet:NSCharacterSet.decimalDigitCharacterSet.invertedSet].location!=NSNotFound)valid=NO;}z=[p[1]integerValue];x=[p[2]integerValue];y=[p[3]integerValue];valid=valid&&z>=0&&z<=19&&x>=0&&y>=0&&x<(1<<z)&&y<(1<<z);}
 if(!valid){[task didFailWithError:[NSError errorWithDomain:@"WLOC Map" code:400 userInfo:nil]];return;}
 NSString *remote=source[@"url"];NSString *domains=source[@"subdomains"]?:@"a";NSString *subdomain=[domains substringWithRange:NSMakeRange((x+y)%domains.length,1)];for(NSString *name in @[@"{z}",@"{x}",@"{y}",@"{s}"]){NSString *value=[name isEqual:@"{z}"]?[@(z)stringValue]:[name isEqual:@"{x}"]?[@(x)stringValue]:[name isEqual:@"{y}"]?[@(y)stringValue]:subdomain;remote=[remote stringByReplacingOccurrencesOfString:name withString:value];}if(z>[source[@"maxZoom"]integerValue]){[task didFailWithError:[NSError errorWithDomain:@"WLOC Map" code:400 userInfo:nil]];return;}

 NSValue *key=[NSValue valueWithNonretainedObject:task];__weak MapTiles *weakSelf=self;
 NSURLSessionDataTask *request=[self.session dataTaskWithURL:[NSURL URLWithString:remote] completionHandler:^(NSData *data,NSURLResponse *response,NSError *error){dispatch_async(dispatch_get_main_queue(),^{MapTiles *owner=weakSelf;if(!owner.tasks[key])return;[owner.tasks removeObjectForKey:key];NSInteger code=[(NSHTTPURLResponse *)response statusCode];if(error||code!=200||![response.MIMEType hasPrefix:@"image/"]||!data.length||![UIImage imageWithData:data]){NSError *e=error?:[NSError errorWithDomain:@"Map HTTP" code:code userInfo:nil];if(owner.failure)owner.failure([NSString stringWithFormat:@"%@：%@ %ld",[NSURL URLWithString:remote].host,e.domain,(long)e.code]);[task didFailWithError:e];return;}[task didReceiveResponse:[[NSURLResponse alloc]initWithURL:url MIMEType:response.MIMEType expectedContentLength:data.length textEncodingName:nil]];[task didReceiveData:data];[task didFinish];});}];self.tasks[key]=request;[request resume];
}
- (void)webView:(WKWebView *)webView stopURLSchemeTask:(id<WKURLSchemeTask>)task{NSValue *key=[NSValue valueWithNonretainedObject:task];[self.tasks[key] cancel];[self.tasks removeObjectForKey:key];}
- (void)dealloc{[_session invalidateAndCancel];}
@end
// WebKit retains message handlers; use a weak forwarder so the map can be released.
@interface MapMessages:NSObject <WKScriptMessageHandler>
@property(nonatomic,weak) MapPanel *owner;
@end
@implementation MapMessages
- (void)userContentController:(WKUserContentController *)controller didReceiveScriptMessage:(WKScriptMessage *)message{[self.owner userContentController:controller didReceiveScriptMessage:message];}
@end
@implementation MapPanel
- (instancetype)initWithFrame:(CGRect)frame{if((self=[super initWithFrame:frame])){WKWebViewConfiguration *config=[WKWebViewConfiguration new];MapMessages *messages=[MapMessages new];messages.owner=self;[config.userContentController addScriptMessageHandler:messages name:@"map"];MapTiles *tiles=[MapTiles new];__weak MapPanel *weakSelf=self;tiles.failure=^(NSString *s){if(weakSelf.diagnostic)weakSelf.diagnostic(s);};[config setURLSchemeHandler:tiles forURLScheme:@"wloc-tile"];_web=[[WKWebView alloc]initWithFrame:CGRectZero configuration:config];_web.navigationDelegate=self;_web.scrollView.scrollEnabled=NO;_web.translatesAutoresizingMaskIntoConstraints=NO;[self addSubview:_web];[NSLayoutConstraint activateConstraints:@[[_web.topAnchor constraintEqualToAnchor:self.topAnchor],[_web.bottomAnchor constraintEqualToAnchor:self.bottomAnchor],[_web.leadingAnchor constraintEqualToAnchor:self.leadingAnchor],[_web.trailingAnchor constraintEqualToAnchor:self.trailingAnchor]]];NSURL *url=[NSBundle.mainBundle URLForResource:@"index" withExtension:@"html" subdirectory:@"Map"];if(url)[_web loadFileURL:url allowingReadAccessToURL:[url URLByDeletingLastPathComponent]];}return self;}
- (void)userContentController:(WKUserContentController *)controller didReceiveScriptMessage:(WKScriptMessage *)message{if(!message.frameInfo.isMainFrame||![message.body isKindOfClass:NSDictionary.class])return;NSDictionary *v=message.body;NSString *type=v[@"type"];if([type isEqual:@"viewport"]){BOOL valid=YES;for(NSString *key in @[@"latitude",@"longitude",@"latitudeDelta",@"longitudeDelta"])if(![v[key]isKindOfClass:NSNumber.class]||!isfinite([v[key]doubleValue]))valid=NO;if(valid&&fabs([v[@"latitude"]doubleValue])<=90&&fabs([v[@"longitude"]doubleValue])<=180&&[v[@"latitudeDelta"]doubleValue]>0&&[v[@"latitudeDelta"]doubleValue]<=180&&[v[@"longitudeDelta"]doubleValue]>0&&[v[@"longitudeDelta"]doubleValue]<=360)self.viewport=v;}else if([type isEqual:@"diagnostic"]){if(self.diagnostic&&[v[@"message"]isKindOfClass:NSString.class])self.diagnostic(v[@"message"]);}else if([type isEqual:@"pick"]){double lat=[v[@"latitude"]doubleValue],lon=[v[@"longitude"]doubleValue];if([v[@"latitude"]isKindOfClass:NSNumber.class]&&[v[@"longitude"]isKindOfClass:NSNumber.class]&&isfinite(lat)&&isfinite(lon)&&fabs(lat)<=90&&fabs(lon)<=180&&self.selection)self.selection(lat,lon);}else if([type isEqual:@"tiles"]){self.tilesVisible=[v[@"visible"]boolValue];self.currentSource=[v[@"source"]integerValue];if(self.notice)self.notice([v[@"message"]isKindOfClass:NSString.class]?v[@"message"]:@"");}}
- (void)showLatitude:(double)lat longitude:(double)lon selected:(BOOL)selected{if(!isfinite(lat)||!isfinite(lon)||fabs(lat)>90||fabs(lon)>180)return;self.pendingPoint=@[@(lat),@(lon),@(selected)];[self.web evaluateJavaScript:[NSString stringWithFormat:@"window.setPoint && setPoint(%.8f,%.8f,%@)",lat,lon,selected?@"true":@"false"] completionHandler:nil];}
- (void)showCurrentLatitude:(double)lat longitude:(double)lon accuracy:(double)accuracy{if(!isfinite(lat)||!isfinite(lon)||!isfinite(accuracy)||fabs(lat)>90||fabs(lon)>180||accuracy<0)return;self.pendingCurrentLocation=@[@(lat),@(lon),@(accuracy)];[self.web evaluateJavaScript:[NSString stringWithFormat:@"window.showCurrentLocation && showCurrentLocation(%.8f,%.8f,%.2f)",lat,lon,accuracy] completionHandler:nil];}
- (void)source:(NSInteger)index{self.tilesVisible=NO;[self.web evaluateJavaScript:[NSString stringWithFormat:@"window.setSource && setSource(%ld)",(long)MAX(0,MIN(index,5))] completionHandler:nil];}
- (void)mode:(NSString *)mode{if(![@[@"auto",@"amap",@"osm"]containsObject:mode])mode=@"auto";self.pendingMapMode=mode;[self.web evaluateJavaScript:[NSString stringWithFormat:@"window.setMapMode && setMapMode('%@')",mode] completionHandler:nil];}
- (void)retry{[self.web evaluateJavaScript:@"window.retryMap && retryMap()" completionHandler:nil];}
- (void)webView:(WKWebView *)webView didFinishNavigation:(WKNavigation *)navigation{[self mode:self.pendingMapMode?:@"auto"];if(self.pendingPoint)[self showLatitude:[self.pendingPoint[0]doubleValue] longitude:[self.pendingPoint[1]doubleValue] selected:[self.pendingPoint[2]boolValue]];if(self.pendingCurrentLocation)[self showCurrentLatitude:[self.pendingCurrentLocation[0]doubleValue] longitude:[self.pendingCurrentLocation[1]doubleValue] accuracy:[self.pendingCurrentLocation[2]doubleValue]];if(self.notice&&!self.tilesVisible)self.notice(@"地图引擎就绪，正在下载图像；点击地图即可选位置。");}
- (void)webView:(WKWebView *)webView didFailNavigation:(WKNavigation *)navigation withError:(NSError *)error{if(self.notice)self.notice(error.localizedDescription);}
- (void)webViewWebContentProcessDidTerminate:(WKWebView *)webView{self.tilesVisible=NO;[webView reload];}
- (void)webView:(WKWebView *)webView decidePolicyForNavigationAction:(WKNavigationAction *)action decisionHandler:(void (^)(WKNavigationActionPolicy))handler{if([action.request.URL.scheme isEqual:@"https"]&&action.navigationType==WKNavigationTypeLinkActivated){[UIApplication.sharedApplication openURL:action.request.URL options:@{} completionHandler:nil];handler(WKNavigationActionPolicyCancel);}else handler([action.request.URL.scheme isEqual:@"file"]?WKNavigationActionPolicyAllow:WKNavigationActionPolicyCancel);}
@end
